INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
  (54933, 0, 0, 0, 0, 0, 0, 0, 0, 'You have my thanks, $n. I must leave this world, but I wish you luck. \n\nTake my blessing. May it aid you against these monsters.', 0),
  (54951, 0, 0, 0, 0, 0, 0, 0, 0, 'We''re ready to move. Let''s find that missing expedition.', 0),
  (54952, 0, 0, 0, 0, 0, 0, 0, 0, 'The others... taken... \n\nNeed... food...', 0),
  (55122, 0, 0, 0, 0, 0, 0, 0, 0, 'Excellent work. Let''s get the survivors back on their feet.', 0),
  (55173, 0, 0, 0, 0, 0, 0, 0, 0, 'I''ve got some good news and some very, very bad news.', 0),
  (55174, 0, 0, 0, 0, 0, 0, 0, 0, '<Alaria quickly eats the meat that you cooked.>\n\nBy the Light... I feel so much better.\n\nYou need to keep moving... quilboar have kidnapped the expedition, including Captain Garrick''s son!', 0),
  (55184, 1, 0, 0, 0, 0, 0, 0, 0, 'Good work. I hope those quilboar learn that necromancy is not a path to power.', 0),
  (55186, 4, 0, 0, 0, 0, 0, 0, 0, 'Thanks for saving my life! They said this would be a run of the mill, uneventful expedition.\n\nIt definitely was NOT! And I couldn''t be happier!', 0),
  (55193, 4, 0, 0, 0, 0, 0, 0, 0, 'There''s no problem a little re-sizing can''t fix! Let''s find something to stomp those undead flat!', 0),
  (55194, 0, 0, 0, 0, 0, 0, 0, 0, 'All stocked up? That''s great.\n\nPrivate Cole and Quartermaster Richter also found this bag in the nearby ruins. They thought you might make good use of it.', 0),
  (55196, 25, 0, 0, 0, 0, 0, 0, 0, 'It seems the harpies are up to no good. We''ll need your help with this.', 0),
  (55639, 0, 0, 0, 0, 0, 0, 0, 0, 'Ralia Dreamchaser is a druid of the Cenarion Circle, an order dedicated to protecting the wilds of Azeroth.\n\nThank you for rescuing her. Her aid is sure to be of use against the ogres.', 0),
  (55763, 5, 0, 0, 0, 0, 0, 0, 0, 'Ye rescued me from a grim fate! Bein'' a practicin'' mage, I always figured one of me own spells would do me in, not a harpy!', 0),
  (55764, 273, 0, 0, 0, 0, 0, 0, 0, 'That should keep our camp safe for now. We must hurry and stop whatever these ogres have planned.', 0),
  (55879, 66, 0, 0, 0, 0, 0, 0, 0, 'Thank you, stranger. I thought I was going to be punished for failing to save my friends.\n\nI''m relieved that I was mistaken.', 0),
  (55881, 1, 0, 0, 0, 0, 0, 0, 0, 'The foul magic in this area is dissipating. I think we''re safe for now.', 0),
  (55882, 0, 0, 0, 0, 0, 0, 0, 0, 'I''m relieved you rescued Meredy. That''s one more life saved and one fewer sacrificed.\n\nAnd I''m glad to see you helped Henry get back to his old self.\n\nWe''ll work with Meredy to figure out a plan of action.', 0),
  (55965, 6, 0, 0, 0, 0, 0, 0, 0, 'A giant pit of spiders right on our doorstep! Aren''t we the lucky ones?', 0),
  (55981, 0, 0, 0, 0, 0, 0, 0, 0, 'We''re close to stopping all of this. We just need to push a little further.', 0),
  (55988, 4, 0, 0, 0, 0, 0, 0, 0, 'This should buy us enough time to stop the ritual!', 0),
  (55989, 273, 0, 0, 0, 0, 0, 0, 0, 'Great work! I''ll have tae tell Lindie that his bombs worked perfectly.', 0),
  (55990, 5, 0, 0, 0, 0, 0, 0, 0, 'Thank you for saving me, but we have no time to lose. The ogres will not stop until they have raised the dragon!', 0),
  (55991, 0, 0, 0, 0, 0, 0, 0, 0, 'It''s good to be back in Stormwind. \n\nI must report our mission''s success to the king, but I have an idea for what you can do in the meantime...', 0),
  (55992, 0, 0, 0, 0, 0, 0, 0, 0, 'It seems things are finally looking up for us. I think it''s time we returned to Stormwind.', 0),
  (56034, 0, 0, 0, 0, 0, 0, 0, 0, 'I never thought I''d be so relieved to be face to face with a giant, scientifically enhanced boar.\n\nLet''s go save my son.', 0),
  (56344, 0, 0, 0, 0, 0, 0, 0, 0, 'All right, $n. I hope you''re a good actor, because you''re about to play to a very tough crowd.', 0),
  (56775, 0, 0, 0, 0, 0, 0, 0, 0, 'Good, looks like you''ve kept up your $c training during our voyage.\n\nI''m concerned about the sudden turn in weather. Spar with Private Cole while I speak with the ship''s crew.\n\nCole''s report will determine where we''ll place you on our initial expedition team.', 0),
  (56839, 0, 0, 0, 0, 0, 0, 0, 0, '<You find a cache of treasure, just like the ogres'' sign mentioned!>', 0),
  (58208, 0, 0, 0, 0, 0, 0, 0, 0, 'This ship may not make it to the island.\n\nHold on to something sturdy and stick with your fellow recruits. We''ll get through this.', 0),
  (58209, 66, 0, 0, 0, 0, 0, 0, 0, 'You''re a skilled $c, recruit. I think you''ll prove a welcome addition to the main rescue team.', 0),
  (58953, 0, 0, 0, 0, 0, 0, 0, 0, 'There''s no time fer chatting. I''m going tae bless ye with the power to resurrect.\n\nI''d give ye a bit more ceremony, but we got an urgent problem on our hands.\n\nIf we don''t hurry, the souls of these poor recruits will be consumed by the ogre''s necromancy!', 0),
  (58960, 0, 0, 0, 0, 0, 0, 0, 0, 'Ye''ve got what it takes tae become a great priest one day.\n\nMe? Oh, me body is long since decayed. But I can rest easy now that I know these ogres are going tae be stopped.', 0),
  (59002, 0, 0, 0, 0, 0, 0, 0, 0, 'My pack and I are too weak to oppose the dark forces on this island.\n\nWe will use the last of our strength to grant you our power.\n\nUse it to rid the island of the ogres'' necromancy.\n\nFree the countless souls they have trapped here.', 0),
  (59254, 0, 0, 0, 0, 0, 0, 0, 0, 'Fine work, $n. Let''s speak with Alaria and hunt down those quilboar.', 0),
  (59342, 0, 0, 0, 0, 0, 0, 0, 0, 'You''ve got a loyal companion by your side. Take good care of them, and they''ll take care of you.', 0),
  (59350, 273, 1, 0, 0, 0, 0, 0, 0, 'Good! I can sense the blessing of the spirits flowing through you.\n\nFocus, and you should find that you can take on a new form.', 0),
  (59355, 0, 0, 0, 0, 0, 0, 0, 0, 'With a little work, this can become a trap you can use. \n\nPart of being a hunter means making use of what your surroundings provide.', 0),
  (59356, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you for the help, $n. I have one last lesson to impart--calling a different companion to your side.\n\nThere are plenty of wild beasts on this island. See which ones you can tame.', 0),
  (59926, 0, 397, 0, 0, 0, 259, 0, 0, 'Good, you''ve kept training since we set sail.\n\nI must investigate this storm. Some unnatural force is behind it.\n\nSpar with Throg. He will assess your skills and decide on your role once we make landfall.', 0),
  (59927, 25, 0, 0, 0, 0, 0, 0, 0, 'You show promise, $c. Perhaps you too will find glory on the island!', 0),
  (59928, 397, 0, 0, 0, 0, 0, 0, 0, 'Some force is manipulating this storm!\n\nStay near me when the ship crashes. I''ll keep you safe.', 0),
  (59929, 0, 0, 0, 0, 0, 0, 0, 0, 'Excellent work. Let''s get the survivors back on their feet.', 0),
  (59930, 0, 0, 0, 0, 0, 0, 0, 0, 'We''re back on our feet. Now let''s move. The lost expedition is somewhere on this island.', 0),
  (59931, 0, 0, 0, 0, 0, 0, 0, 0, 'I''m stabilizing Won''sa wounds, but she needs food before she starves.', 0),
  (59932, 0, 0, 0, 0, 0, 0, 0, 0, '<Won''sa quickly eats the meat that you cooked.>\n\nLooks I not gonna be knockin'' on Bwonsamdi''s door, after all.\n\nYa best hurry. Da quilboar have some of da expedition!', 0),
  (59933, 0, 0, 0, 0, 0, 0, 0, 0, 'You''re ready to slaughter the quilboar! Let''s speak to Won''sa and see what she knows.', 0),
  (59935, 0, 0, 0, 0, 0, 0, 0, 0, 'I have good news... and most unfortunate news.', 0),
  (59937, 0, 0, 0, 0, 0, 0, 0, 0, 'Fine work. The lessons you learn from the inimitable Mithdran Dawntracker will last you a lifetime.\n\nNow, down to the business of our quilboar foes...', 0),
  (59938, 4, 11, 0, 0, 0, 0, 0, 0, 'You sure got some guts! I respect that. I joined this expedition thinkin'' it''d be a quick and easy way to make a little profit.\n\nBut now with all this shadow magic and crazy ogres... maybe I can make a LOT of profit!', 0),
  (59939, 66, 0, 0, 0, 0, 0, 0, 0, 'A fine job. The quilboar seem to be keeping their distance. Perhaps they learned their lesson.', 0),
  (59940, 4, 0, 0, 0, 0, 0, 0, 0, 'All right, time to bend some rules and make a giant boar!', 0),
  (59941, 397, 0, 0, 0, 0, 0, 0, 0, 'Cork turned the device meant for enlarging things into a weapon capable of untold destruction?\n\nThe goblins in Orgrimmar may give him an award for this.', 0),
  (59942, 66, 0, 0, 0, 0, 0, 0, 0, 'Hmph, it''s about time. I suppose you''ll need my help to find out what else is going on.', 0),
  (59943, 2, 0, 0, 0, 0, 0, 0, 0, 'I have found the missing member of the expedition... but we have many problems to deal with first.', 0),
  (59944, 4, 11, 0, 0, 0, 0, 0, 0, 'Thanks for the save! They must be desperate for sacrifices if they wanted to use someone who''s already dead.\n\nIf anyone is going to drain my life essence to use in a forbidden ritual, it''s going to be me!', 0),
  (59945, 1, 0, 0, 0, 0, 0, 0, 0, 'The harpies seem to be retreating to their roost. That should give us time to stop the ogres.', 0),
  (59946, 2, 0, 0, 0, 0, 0, 0, 0, 'The harpies grow weaker with their totems destroyed. Let us hope they realize that the Horde is a force to be reckoned with.', 0),
  (59947, 0, 0, 0, 0, 0, 0, 0, 0, 'It is good to see you all back in one piece. You are testament to the Horde''s strength of will!\n\nLet''s hope Gloomburst is as powerful as he is unhinged.', 0),
  (59948, 1, 6, 25, 0, 0, 0, 0, 0, 'A giant pit filled with necrotic energy and spiders.\n\nI used to hate spiders. Now that I''m Forsaken, I don''t think they''re all that bad.\n\nThey will still definitely kill you, though.', 0),
  (59949, 0, 0, 0, 0, 0, 0, 0, 0, 'Crenna Earth-Daughter will be vital to our cause. Her connection to nature will help us understand what the ogres have done to this island.\n\nGood work, recruit.', 0),
  (59950, 0, 0, 0, 0, 0, 0, 0, 0, 'We''ve got to be prepared for anything on this island.\n\nAlso, Throg found this bag nearby and thought you might have use of it.', 0),
  (59951, 4, 1, 0, 0, 0, 0, 0, 0, 'Good! I can sense the blessing of the spirits flowing through you.\n\nFocus, and you should find that you can take on a new form.', 0),
  (59952, 1, 0, 0, 0, 0, 0, 0, 0, 'With a little work, this can become an effective trap.\n\nPart of what makes a real hunter is the resourcefulness to use what your environment provides.', 0),
  (59953, 6, 11, 378, 0, 0, 0, 0, 0, 'I admit, I am rather ashamed I did not immediately recognize this beast.\n\nIt must be quite resilient if it was able to survive this long on its own!\n\nHere, let me teach you another trick. You''ll want to have multiple pets to switch between if you''re to be a hunter of any worth.', 0),
  (59970, 0, 0, 0, 0, 0, 0, 0, 0, 'Our bargain has been struck.\n\nCall upon me from the Void, and I will answer.\n\n<The voidwalker looks at the goblin''s corpse.>\n\nLet us see if you are stronger than those who came before you.', 0),
  (59975, 0, 0, 0, 0, 0, 0, 0, 0, 'Darkmaul Citadel looms ahead. \n\nHerbert''s proposed plan is... unconventional.', 0),
  (59978, 0, 0, 0, 0, 0, 0, 0, 0, 'There may just be a way that we can save Warlord Thunderwalker.', 0),
  (59979, 1, 0, 0, 0, 0, 0, 0, 0, 'That should weaken the ogres long enough for us to put an end to their plotting.', 0),
  (59980, 6, 11, 0, 0, 0, 0, 0, 0, 'I''m glad to see the catapults are shattered, and you''re in one piece.\n\nIt can be rare to achieve both with Cork''s inventions.', 0),
  (59981, 2, 5, 0, 0, 0, 0, 0, 0, 'Thank you for the aid, but saving me will not stop the ogres. \n\nThey already have enough life essence to complete the ritual!', 0),
  (59984, 0, 0, 0, 0, 0, 0, 0, 0, 'Victory is ours today, $n. More must be done, and I believe you are ready to go off to new adventures.', 0),
  (59985, 0, 0, 0, 0, 0, 0, 0, 0, 'The Dragon Isles is a beautiful place, $n.\n\nI must be on my way, but first let me give you a hand.', 0),
  (60162, 1, 66, 0, 0, 0, 0, 0, 0, 'I don''t believe there is anything left to teach you, $n. \n\nNow you must go forth and find more beasts to tame and call your own.\n\nIf you ever need to store or retrieve your pets, speak with me or any other stable masters you encounter in your travels.', 0),
  (60168, 0, 0, 0, 0, 0, 0, 0, 0, 'Excellent work, $n. There''s nothing left for me to teach you.\n\nGather as many wild beasts as you''d like. Just make sure not to lose focus on the ogres who are trying to kill us.', 0),
  (85679, 0, 0, 0, 0, 0, 0, 0, 0, 'You''ll want to keep your gear repaired if you want to earn honor and glory amongst the Horde!', 0);
